import{a as n}from"./index-DCsbF_u_.js";const i={setup:{title:"Set up your project",desc:"Your agent team is built from the plan you write here. Once generation starts it runs in the background — you can use the app while the fleet lands, and every finished agent is saved the moment it arrives.",switchLang:"العربية",switchLangAria:"Switch the interface to Arabic",stepsAria:"Setup progress",stepOf:(e,s)=>`Step ${e} of ${s}`,stepDone:"completed",stepCurrent:"current step",steps:{preflight:"Tooling",plan:"Your plan",fleet:"The fleet",done:"Done"},pfTitle:"Connect your tooling",pfDesc:"The build loop shells out to the GitHub CLI and to Claude Code, so both must be authenticated before anything can run. The last check actually executes a headless prompt — authentication can report healthy while execution still fails.",pfRun:"Run the checks",pfRunning:"Checking…",pfRerun:"Run the checks again",pfResults:"Results",pfRequired:"required",pfRemedy:"Fix it with",pfFailing:"Some required checks are failing. Fix them and run this again.",pfEmptyTitle:"Nothing checked yet",pfEmptyDesc:"Run the checks to see whether this machine can build and run a fleet.",pfStatus:{pass:"Passing",fail:"Failing",warn:"Warning",skip:"Skipped"},planTitle:"Describe what you want to build",planDesc:"This goes to the fleet-builder, which reads your repository and designs the team around it. Be specific about surfaces, stack and the boundaries you care about — the fleet is only ever as specific as the plan.",planLabel:"Project plan",planHint:"Markdown is fine. You can rewrite it later and generate again.",planPlaceholder:"e.g. A bilingual EN/AR media-monitoring dashboard. Ingests RSS and the X API into Postgres, clusters into topics, shows analysts a daily briefing. Surfaces: marketing site, analyst dashboard, admin panel. Must be RTL-correct. I need someone owning collection adapters, someone owning the analyst UI, someone owning the schema, and someone checking Arabic copy before anything ships.",planShort:e=>`${e} more character${e===1?"":"s"} before you can continue`,planCount:e=>`${e} characters`,planContinue:"Continue",fleetTitle:"Build the team",fleetDesc:"The fleet-builder explores your repository with read-only tools and proposes a roster; the server writes the files. It never writes them itself — that would mean handing full write access to a session that just read an untrusted plan.",fleetEmptyTitle:"The roster is empty",fleetEmptyDesc:"Nothing has been generated yet. The fleet-builder designs the roster from your plan, and each agent is saved to the database the moment it is written.",issuesLabel:"Also break my plan into issues",issuesShort:"Off by default. Ticking it spends more and puts work on the board.",issuesArmed:"This will spend money beyond the fleet itself:",issuesPoints:["One model call per issue, capped at 15 issues.","The issues land on the board already assigned to this fleet.","They arrive held for your review — but once you release them, agents can claim them and spend on them unattended."],issuesConfirmTitle:"Generate the fleet and the issues?",issuesConfirmDesc:"The fleet is generated either way. Ticking the issues pass adds a second run of paid model calls on top of it.",issuesConfirmCta:"Generate both",genStart:"Generate the fleet",genResume:"Continue generating",genStarting:"Starting…",genResumeNote:"Continuing does not start over. Every item already saved is skipped and only the missing ones are bought.",genResumeFrom:(e,s)=>`Resumes at item ${e+1}: the first ${e} of ${s} are already saved and will not be paid for again.`,progStarting:"Starting…",progRoster:"Designing the roster…",progIssues:"Breaking the plan into issues…",progStage:(e,s,t)=>`Writing ${e} ${s} of ${t}`,progStopped:(e,s)=>`Stopped — ${e} of ${s} finished and saved`,progReady:"Fleet ready",progItems:(e,s)=>`${e} of ${s} items saved`,progPending:e=>`${e} item${e===1?"":"s"} not started yet`,progSpend:"Spent on this run so far",progStageLabel:"Stage",progLive:"Live",progIssuesLanded:e=>`${e} issue${e===1?"":"s"} from your plan are on the board, held for your review — release them when you have read them.`,bgContinue:"Continue to the app",bgNote:"The build keeps running in the background. Progress and spend stay visible in the bar at the top of the app.",rosterHeading:"Saved roster",rosterNote:"Read from the database, not from the run — every agent here is already written and survives a failure.",disabled:"disabled",disabledWhy:"Generated agents land switched off. A human turns them on.",memories:e=>`${e} memor${e===1?"y":"ies"}`,finish:"Finish setup and open the dashboard",doneRunningTitle:"Your fleet is being built",doneRunningDesc:"Setup is done from your side. Generation runs in the background and every finished agent is saved the moment it lands, so there is nothing to wait for here — the bar at the top of the app keeps showing progress and spend until the fleet is ready.",doneFailedTitle:"Generation stopped",doneFailedDesc:(e,s)=>`${e} of ${s} items finished and were saved. Continuing resumes from there and buys only the missing items — it does not start over.`,doneOkTitle:"Setup is complete",doneOkDesc:e=>`${e} agent${e===1?" is":"s are"} registered. Generated agents start switched off — enable the ones you want working before the loop picks up issues.`,openDashboard:"Open the dashboard",errorHeading:"Something went wrong"},profile:{title:"Your profile",desc:"Who you are signed in as, and how this app behaves for you.",loading:"Loading your profile…",accountHeading:"Account",emailLabel:"Email",emailHint:"This is the identity the session was issued to. It is set by your sign-in and cannot be edited here.",rolesLabel:"Roles",rolesHint:"Roles decide what you may reach. Only an administrator can change them.",noRoles:"No roles assigned",prefsHeading:"Preferences",langLabel:"Interface language",langHint:"Changes every screen and, for Arabic, the whole layout direction. Remembered on this browser.",save:"Save preferences",saving:"Saving…",saved:"Saved",revert:"Undo",noChanges:"Nothing to save — this is already your current setting.",dirty:"Not saved yet. The interface changes when you save.",securityHeading:"Security",passwordLabel:"Password",passwordHint:"We do not show or edit passwords here. Changing one starts with a single-use code sent to your email.",passwordCta:"Send a password reset code",passwordSending:"Sending…",passwordSent:"Code sent. Check your email, then continue on the reset screen.",resetLink:"Open the reset screen",passwordConfirmTitle:"Send a password reset code?",passwordConfirmDesc:"A single-use code is emailed to your address. Your current password keeps working until you finish the reset.",passwordConfirmPoints:["The code is emailed to the address on this account.","It is single-use, and your current password keeps working until the reset is finished.","You finish the change on the reset screen."],passwordConfirmCta:"Send the code",sessionHeading:"This browser",signOutLabel:"Signed in on this device",signOutHint:"Ends the session here only. Anything running on the server keeps running.",signOut:"Sign out",signingOut:"Signing out…"}},a={setup:{title:"إعداد مشروعك",desc:"يُبنى فريق الوكلاء من الخطة التي تكتبها هنا. وبمجرد أن يبدأ التوليد يعمل في الخلفية — يمكنك استخدام التطبيق بينما يكتمل الأسطول، ويُحفظ كل وكيل فور الانتهاء منه.",switchLang:"English",switchLangAria:"تحويل الواجهة إلى الإنجليزية",stepsAria:"تقدّم الإعداد",stepOf:(e,s)=>`الخطوة ${e} من ${s}`,stepDone:"مكتملة",stepCurrent:"الخطوة الحالية",steps:{preflight:"الأدوات",plan:"خطتك",fleet:"الأسطول",done:"تم"},pfTitle:"اربط أدواتك",pfDesc:"تستدعي حلقة البناء واجهة GitHub السطرية و‏Claude Code، لذا يجب أن يكون كلاهما موثّقًا قبل تشغيل أي شيء. الفحص الأخير ينفّذ فعليًا طلبًا بلا واجهة — فقد تبدو المصادقة سليمة بينما يفشل التنفيذ.",pfRun:"تشغيل الفحوصات",pfRunning:"جارٍ الفحص…",pfRerun:"إعادة تشغيل الفحوصات",pfResults:"النتائج",pfRequired:"مطلوب",pfRemedy:"الإصلاح عبر",pfFailing:"بعض الفحوصات المطلوبة تفشل. أصلحها ثم شغّلها من جديد.",pfEmptyTitle:"لم يُفحص شيء بعد",pfEmptyDesc:"شغّل الفحوصات لتعرف ما إذا كان هذا الجهاز قادرًا على بناء أسطول وتشغيله.",pfStatus:{pass:"ناجح",fail:"فاشل",warn:"تحذير",skip:"متجاوَز"},planTitle:"صِف ما تريد بناءه",planDesc:"تذهب هذه الخطة إلى باني الأسطول، الذي يقرأ مستودعك ويصمّم الفريق حوله. كن محدّدًا في الواجهات والتقنيات والحدود التي تهمّك — فالأسطول لا يكون أدقّ من الخطة أبدًا.",planLabel:"خطة المشروع",planHint:"تنسيق Markdown مقبول. يمكنك إعادة كتابتها لاحقًا وتوليد الأسطول من جديد.",planPlaceholder:"مثال: لوحة رصد إعلامي ثنائية اللغة (عربي/إنجليزي). تسحب RSS وواجهة X إلى Postgres، تجمّعها في موضوعات، وتعرض للمحلّلين موجزًا يوميًا. الواجهات: موقع تعريفي، لوحة محلّلين، لوحة إدارة. يجب أن تكون سليمة في الاتجاه من اليمين لليسار. أحتاج من يملك محوّلات الجمع، ومن يملك واجهة المحلّل، ومن يملك المخطط، ومن يراجع النصّ العربي قبل أي إطلاق.",planShort:e=>`تبقّى ${e} حرفًا قبل أن تتمكّن من المتابعة`,planCount:e=>`${e} حرفًا`,planContinue:"متابعة",fleetTitle:"ابنِ الفريق",fleetDesc:"يستكشف باني الأسطول مستودعك بأدوات للقراءة فقط ويقترح قائمة الفريق؛ والخادم هو من يكتب الملفات. لا يكتبها الباني بنفسه أبدًا — فذلك يعني منح صلاحية كتابة كاملة لجلسة قرأت للتوّ خطة غير موثوقة.",fleetEmptyTitle:"قائمة الفريق فارغة",fleetEmptyDesc:"لم يُولَّد شيء بعد. يصمّم باني الأسطول القائمة من خطتك، ويُحفظ كل وكيل في قاعدة البيانات فور كتابته.",issuesLabel:"قسّم خطتي إلى مهام أيضًا",issuesShort:"معطّل افتراضيًا. تفعيله ينفق مالًا إضافيًا ويضع عملًا على اللوحة.",issuesArmed:"سينفق هذا مالًا يتجاوز الأسطول نفسه:",issuesPoints:["طلب نموذج واحد لكل مهمة، بحدّ أقصى 15 مهمة.","تصل المهام إلى اللوحة مُسندة إلى هذا الأسطول.","تصل محجوزة لمراجعتك — لكن بمجرد أن تُفرج عنها، يمكن للوكلاء أخذها والإنفاق عليها دون إشراف."],issuesConfirmTitle:"توليد الأسطول والمهام معًا؟",issuesConfirmDesc:"سيُولَّد الأسطول في الحالتين. تفعيل تقسيم المهام يضيف جولة ثانية من طلبات النماذج المدفوعة فوقه.",issuesConfirmCta:"توليد الاثنين",genStart:"توليد الأسطول",genResume:"متابعة التوليد",genStarting:"جارٍ البدء…",genResumeNote:"المتابعة ليست بداية من الصفر. يُتخطّى كل عنصر محفوظ ولا يُشترى إلا الناقص.",genResumeFrom:(e,s)=>`تستأنف من العنصر ${e+1}: أول ${e} من ${s} محفوظة بالفعل ولن يُدفع ثمنها مرة أخرى.`,progStarting:"جارٍ البدء…",progRoster:"جارٍ تصميم قائمة الفريق…",progIssues:"جارٍ تقسيم الخطة إلى مهام…",progStage:(e,s,t)=>`جارٍ كتابة ${e} ${s} من ${t}`,progStopped:(e,s)=>`توقّف — ${e} من ${s} اكتملت وحُفظت`,progReady:"الأسطول جاهز",progItems:(e,s)=>`${e} من ${s} عنصرًا محفوظة`,progPending:e=>`${e} عنصرًا لم يبدأ بعد`,progSpend:"المنفَق على هذا التشغيل حتى الآن",progStageLabel:"المرحلة",progLive:"مباشر",progIssuesLanded:e=>`${e} مهمة من خطتك على اللوحة، محجوزة لمراجعتك — أفرج عنها بعد أن تقرأها.`,bgContinue:"المتابعة إلى التطبيق",bgNote:"يستمرّ البناء في الخلفية. يبقى التقدّم والإنفاق ظاهرين في الشريط أعلى التطبيق.",rosterHeading:"القائمة المحفوظة",rosterNote:"مقروءة من قاعدة البيانات لا من التشغيل — كل وكيل هنا مكتوب بالفعل ويصمد أمام أي فشل.",disabled:"معطّل",disabledWhy:"الوكلاء المولَّدون يصلون معطّلين. يفعّلهم إنسان.",memories:e=>`${e} ذكرى`,finish:"إنهاء الإعداد وفتح اللوحة",doneRunningTitle:"جارٍ بناء أسطولك",doneRunningDesc:"انتهى دورك في الإعداد. يعمل التوليد في الخلفية ويُحفظ كل وكيل فور اكتماله، فلا شيء ينتظرك هنا — يبقى الشريط أعلى التطبيق يعرض التقدّم والإنفاق حتى يجهز الأسطول.",doneFailedTitle:"توقّف التوليد",doneFailedDesc:(e,s)=>`${e} من ${s} عنصرًا اكتملت وحُفظت. المتابعة تستأنف من هناك ولا تشتري إلا العناصر الناقصة — وهي لا تبدأ من الصفر.`,doneOkTitle:"اكتمل الإعداد",doneOkDesc:e=>`${e} وكيلًا مسجّلين. الوكلاء المولَّدون يبدأون معطّلين — فعّل من تريده للعمل قبل أن تلتقط الحلقة المهام.`,openDashboard:"فتح اللوحة",errorHeading:"حدث خطأ"},profile:{title:"ملفك الشخصي",desc:"بمن سجّلت الدخول، وكيف يتصرّف هذا التطبيق معك.",loading:"جارٍ تحميل ملفك…",accountHeading:"الحساب",emailLabel:"البريد الإلكتروني",emailHint:"هذه هي الهوية التي صدرت لها الجلسة. تحدّدها طريقة تسجيل دخولك ولا يمكن تعديلها هنا.",rolesLabel:"الأدوار",rolesHint:"الأدوار تحدّد ما يمكنك الوصول إليه. لا يغيّرها إلا مدير النظام.",noRoles:"لا أدوار مسندة",prefsHeading:"التفضيلات",langLabel:"لغة الواجهة",langHint:"تغيّر كل الشاشات، ومع العربية تغيّر اتجاه التخطيط بالكامل. تُحفظ على هذا المتصفح.",save:"حفظ التفضيلات",saving:"جارٍ الحفظ…",saved:"تم الحفظ",revert:"تراجع",noChanges:"لا شيء لحفظه — هذا هو إعدادك الحالي بالفعل.",dirty:"لم يُحفظ بعد. تتغيّر الواجهة عند الحفظ.",securityHeading:"الأمان",passwordLabel:"كلمة المرور",passwordHint:"لا نعرض كلمات المرور ولا نعدّلها هنا. يبدأ التغيير برمز يُستخدم مرة واحدة يُرسل إلى بريدك.",passwordCta:"إرسال رمز إعادة تعيين كلمة المرور",passwordSending:"جارٍ الإرسال…",passwordSent:"أُرسل الرمز. تحقّق من بريدك ثم أكمل في شاشة إعادة التعيين.",resetLink:"فتح شاشة إعادة التعيين",passwordConfirmTitle:"إرسال رمز إعادة تعيين كلمة المرور؟",passwordConfirmDesc:"يُرسل رمز يُستخدم مرة واحدة إلى بريدك. تبقى كلمة مرورك الحالية صالحة حتى تُتمّ إعادة التعيين.",passwordConfirmPoints:["يُرسل الرمز إلى البريد المسجّل على هذا الحساب.","يُستخدم مرة واحدة، وتبقى كلمة مرورك الحالية صالحة حتى تكتمل إعادة التعيين.","تُكمل التغيير في شاشة إعادة التعيين."],passwordConfirmCta:"إرسال الرمز",sessionHeading:"هذا المتصفح",signOutLabel:"مسجّل الدخول على هذا الجهاز",signOutHint:"ينهي الجلسة هنا فقط. ما يعمل على الخادم يواصل عمله.",signOut:"تسجيل الخروج",signingOut:"جارٍ تسجيل الخروج…"}},r=()=>{const{language:e,isRTL:s}=n();return{S:e==="ar"?a:i,isRTL:s,language:e}};export{r as u};
